fn solve(s: Vec<char>) -> &'static str {
    let mut stack: Vec<char> = Vec::new();
    let mut pairs_removed = 0;

    for &c in &s {
        if let Some(&top) = stack.last() {
            if top == c {
                // Found a pair, pop the stack and increment the count
                stack.pop();
                pairs_removed += 1;
            } else {
                // No pair, push the current character onto the stack
                stack.push(c);
            }
        } else {
            // Stack is empty, just push the current character
            stack.push(c);
        }
    }

    // Check if the number of pairs removed is odd or even
    if pairs_removed % 2 == 1 {
        "Yes"
    } else {
        "No"
    }
}